// Generated by prepare_submissions.py from submissions.json. Edit the template, then regenerate.
// Read-only check of the submission layer against expected-manifest.json. Run it after the last trace chunk,
// then again after saving, closing and reopening the model. It checks model structure only; it says nothing
// about whether a submission is complete or compliant.
// Each item row: [item id, section, link digest, content digest, model status, build status]. A digest is the
// first 16 hex characters of SHA-256 over sorted lines, as prepare_submissions.py computes them; on a mismatch
// compare the item with its entry in expected-manifest.json.
assert session.sessionResource.URI.toString().toLowerCase().contains('/fsae-2027-electric-arcadia/'): 'Only the disposable acceptance project is permitted'
assert api.layer('SA').system.summary == 'FSAE2027:bootstrap-v1': 'Missing the acceptance project marker'
def req = api.requirements()
assert req.available() && req.viewpointEnabled()
def vocab = @@VOCAB@@
def items = @@ITEMS@@
def folderRows = @@FOLDERS@@
def decisions = @@DECISIONS@@
def baseline = @@BASELINE@@
def failures = []
def check = { boolean ok, String message -> if (!ok) failures << message }
def sha = { String text -> java.security.MessageDigest.getInstance('SHA-256').digest(text.getBytes('UTF-8')).encodeHex().toString() }
def feature = { element, String name ->
    def value = element.eGet(element.eClass().getEStructuralFeature(name))
    value == null ? '' : value.toString()
}
def contentDigest = { element ->
    def attributes = req.attributes(element)
    def lines = [element.ReqIFIdentifier, feature(element, 'ReqIFLongName'), feature(element, 'ReqIFText'), feature(element, 'ReqIFChapterName')]
    lines += attributes.keySet().sort().collect { it + '=' + attributes[it] }
    sha(lines.join('\n')).substring(0, 16)
}

def modules = req.listModules().collectEntries { [(it.ReqIFIdentifier): it] }
def module = modules[@@MODULE_ID@@]
assert module != null: 'The submission module is missing'
def nodes = [:]
def iterator = module.eAllContents()
while (iterator.hasNext()) {
    def element = iterator.next()
    if (element.eClass().name in ['Folder', 'Requirement']) {
        check(!nodes.containsKey(element.ReqIFIdentifier), 'Duplicate identifier ' + element.ReqIFIdentifier)
        nodes[element.ReqIFIdentifier] = element
    }
}
check(nodes.size() == folderRows.size() + items.size(), 'Expected ' + (folderRows.size() + items.size()) + ' folders and items, found ' + nodes.size())
check(req.requirements(module).size() == @@ITEM_COUNT@@, 'Expected @@ITEM_COUNT@@ items')

// One scan of every layer: satisfy links into the module, and the DEC constraints.
def satisfied = [:].withDefault { [] }
def decisionCounts = [:].withDefault { 0 }
['OA', 'SA', 'LA', 'PA', 'EPBS'].each { layer ->
    def scan = api.layer(layer).eAllContents()
    while (scan.hasNext()) {
        def element = scan.next()
        def className = element.eClass().name
        if (className == 'CapellaOutgoingRelation' && element.relationType?.ReqIFLongName == 'satisfy') {
            def target = element.target
            def id = target?.eClass()?.getEStructuralFeature('ReqIFIdentifier') ? target.ReqIFIdentifier : null
            if (id != null && nodes.containsKey(id) && nodes[id] == target) {
                def source = element.source
                satisfied[id] << layer + '|' + source.eClass().name + '|' + source.eGet(source.eClass().getEStructuralFeature('name'))
            }
        } else if (className == 'Constraint' && element.name != null) {
            decisions.each { if (element.name.startsWith('FSAE2027:' + it + ' ')) decisionCounts[it]++ }
        }
    }
}
decisions.each { check(decisionCounts[it] == 1, it + ' must resolve to exactly one Constraint, found ' + decisionCounts[it]) }

def linksOf = { element ->
    def derive = [], verify = []
    element.ownedRelations.each { relation ->
        def kind = relation.relationType?.ReqIFLongName
        if (relation.eClass().name == 'InternalRelation' && kind == 'derive' && relation.source == element) derive << relation.target.ReqIFIdentifier
        else if (relation.eClass().name == 'CapellaIncomingRelation' && kind == 'verify' && relation.source == element) {
            def target = relation.target
            def owner = target
            def layers = [OperationalAnalysis: 'OA', SystemAnalysis: 'SA', LogicalArchitecture: 'LA', PhysicalArchitecture: 'PA', EPBSArchitecture: 'EPBS']
            while (owner != null && !layers.containsKey(owner.eClass().name)) owner = owner.eContainer()
            verify << layers[owner?.eClass()?.name] + '|' + target.eClass().name + '|' + target.name
        } else failures << 'Unexpected relation on ' + element.ReqIFIdentifier
    }
    [derive: derive, verify: verify, satisfy: satisfied[element.ReqIFIdentifier]]
}
def linkDigest = { links ->
    def lines = links.derive.collect { 'derive|' + it } + links.verify.collect { 'verify|' + it } + links.satisfy.collect { 'satisfy|' + it }
    sha(lines.sort().join('\n')).substring(0, 16)
}
def deriveTargets = [] as Set

folderRows.each { row ->
    def (identifier, parent, derive, satisfy, digest) = row
    def folder = nodes[identifier]
    if (folder == null) { failures << 'Missing folder ' + identifier; return }
    check(folder.eClass().name == 'Folder', identifier + ' is not a Folder')
    check(folder.eContainer() == (parent == @@MODULE_ID@@ ? module : nodes[parent]), identifier + ' has the wrong parent')
    check(contentDigest(folder) == digest, identifier + ' title, text or attributes differ from the manifest')
    def links = linksOf(folder)
    check(links.derive.sort() == derive.collect { 'FSAE-2027-V1:' + it }.sort(), identifier + ' derive links differ')
    check(links.verify.isEmpty() && links.satisfy.sort() == satisfy.sort(), identifier + ' verify or satisfy links differ')
    deriveTargets.addAll(links.derive)
    def attributes = req.attributes(folder)
    check(attributes.submission_id in vocab.submission_id, identifier + ' submission_id outside the vocabulary')
    if (parent == @@MODULE_ID@@) {
        check(attributes.submission_status in vocab.submission_status, identifier + ' submission_status outside the vocabulary')
        check(attributes.submission_penalty_group in vocab.submission_penalty_group, identifier + ' penalty group outside the vocabulary')
    }
}

items.each { row ->
    def (shortId, section, expectedLinks, digest, modelStatus, buildStatus) = row
    def identifier = 'FSAE2027:SUB:item:' + shortId
    def item = nodes[identifier]
    if (item == null) { failures << 'Missing item ' + identifier; return }
    check(item.eClass().name == 'Requirement', identifier + ' is not a Requirement')
    check(item.eContainer() == nodes['FSAE2027:SUB:' + section], identifier + ' is not in section ' + section)
    def attributes = req.attributes(item)
    ['submission_id', 'submission_source_kind', 'submission_model_status', 'submission_status'].each {
        check(attributes[it] in vocab[it], identifier + ' ' + it + ' outside the vocabulary: ' + attributes[it])
    }
    check(attributes.submission_model_status == modelStatus, identifier + ' model status changed')
    check(attributes.submission_status == buildStatus, identifier + ' status is not ' + buildStatus + ' at build time')
    ['submission_value', 'submission_owner', 'submission_due', 'submission_evidence_ref'].each {
        check(attributes[it] == 'TBD', identifier + ' ' + it + ' is not TBD at build time')
    }
    check(contentDigest(item) == digest, identifier + ' title, text or attributes differ from the manifest')
    def links = linksOf(item)
    check(linkDigest(links) == expectedLinks, identifier + ' derive, verify or satisfy links differ from the manifest')
    check(modelStatus == 'absent' || links.derive.size() + links.verify.size() + links.satisfy.size() > 0, identifier + ' is ' + modelStatus + ' but has no typed link')
    deriveTargets.addAll(links.derive.findAll { it.startsWith('FSAE-2027-V1:') })
}

// Every derive target is a pinned source paragraph whose text hash matches the ledger (one digest over all).
def sourceModule = modules['FSAE-2027-V1:source-module']
def sources = req.requirements(sourceModule).collectEntries { [(it.ReqIFIdentifier): it] }
def hashLines = deriveTargets.sort().collect { id ->
    def attributes = sources[id] ? req.attributes(sources[id]) : [:]
    check(attributes.source_sha256 == '@@SOURCE_HASH@@', id + ' is not a pinned source paragraph')
    id + '=' + attributes.source_text_sha256
}
check(deriveTargets.size() == @@TARGET_COUNT@@, 'Expected @@TARGET_COUNT@@ distinct source paragraphs as derive targets, found ' + deriveTargets.size())
check(sha(hashLines.join('\n')) == '@@DIGEST@@', 'Derive-target source text hashes differ from clause-ledger.json')

// The layer adds links only; the source requirements keep their statuses.
def coverage = [:].withDefault { 0 }, verification = [:].withDefault { 0 }
sources.values().each {
    def attributes = req.attributes(it)
    coverage[attributes.coverage_status]++
    verification[attributes.verification_status]++
}
check(sources.size() == baseline.source_requirements, 'Source requirement count changed')
check(([:] + coverage) == baseline.coverage_status, 'Source coverage_status counts changed: ' + coverage)
check(([:] + verification) == baseline.verification_status, 'Source verification_status counts changed: ' + verification)

assert failures.isEmpty(): failures.size() + ' check(s) failed:\n' + failures.take(25).join('\n')
log.info('Submission layer verified: ' + folderRows.size() + ' folders, ' + items.size() + ' items, ' + deriveTargets.size() + ' source paragraphs.')
return [folders: folderRows.size(), items: items.size(), derive_targets: deriveTargets.size(), status: 'structure verified; readiness not claimed']
